BEGIN READ ONLY;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY event_time,archive_id),'[]') FROM (SELECT archive_id,event_time,endpoint,source_file,source_offset,request_body_size,summary_json->'request_origin' origin FROM token_analysis_request_summaries WHERE event_time >= TIMESTAMPTZ '2026-10-26T09:00:00+08:00' AND event_time < TIMESTAMPTZ '2026-10-27T09:00:00+08:00' AND endpoint='/v1/messages' AND summary_json->'request_origin'->>'kind'='ai') x;
ROLLBACK;
SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'rollback_completed',true);

BEGIN READ ONLY;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
SELECT coalesce(jsonb_agg(column_name ORDER BY ordinal_position),'[]') FROM information_schema.columns WHERE table_name='token_analysis_request_summaries' AND column_name IN ('fp_version','fp_state','prefix_end_hash','client_family','source_line_start','source_line_length');
ROLLBACK;
SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'rollback_completed',true);

BEGIN READ ONLY;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
SELECT jsonb_build_object('count',count(*),'human',count(*) FILTER(WHERE summary_json->'request_origin'->>'kind'='human'),'min_origin_version',min((summary_json->'request_origin'->>'version')::int),'max_origin_version',max((summary_json->'request_origin'->>'version')::int)) FROM token_analysis_request_summaries WHERE event_time >= TIMESTAMPTZ '2026-10-26T09:00:00+08:00' AND event_time < TIMESTAMPTZ '2026-10-27T09:00:00+08:00';
ROLLBACK;
SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'rollback_completed',true);
